const log = (m) => process.stderr.write(`[snapshot] ${m}\n`);

async function readJson(p) {
  return JSON.parse(await fsp.readFile(p, "utf8"));
}

async function rimraf(p) {
  await fsp.rm(p, { recursive: true, force: true });
}

async function ensureDir(p) {
  await fsp.mkdir(p, { recursive: true });
}

async function copyDir(src, dst) {
  await ensureDir(dst);
  const ents = await fsp.readdir(src, { withFileTypes: true });
  await Promise.all(
    ents.map(async (e) => {
      const s = path.join(src, e.name);
      const d = path.join(dst, e.name);
      if (e.isDirectory()) {
        await copyDir(s, d);
      } else if (e.isFile()) {
        await ensureDir(path.dirname(d));
        await fsp.copyFile(s, d);
      }
    })
  );
}

function toAliasName(version) {
  // 0.2.0 -> v0_2_0
  const [ma = "0", mi = "0", pa = "0"] = String(version).split(".");
  return `v${ma}_${mi}_${pa}`;
}

/** JS/TS/MDX: import '@hk/weave-ui[/sub]' → '@hk/weave-ui_vM_m_p[/sub]' */
function replaceWeaveImports(code, aliasModule) {
  // 캡처: 앞따옴표, 서브패스(예: /globals.css) 포함
  const re = /(['"])@hk\/weave-ui(\/[^"'`]*)?\1/g;
  return code.replace(re, (m, q, sub = "") => {
    return `${q}@hk/weave-ui_${aliasModule}${sub}${q}`;
  });
}

/** CSS/SCSS: @import "@hk/weave-ui[/sub]"; 또는 @import url("@hk/weave-ui[/sub]"); */
function replaceWeaveCssAtImport(code, aliasModule) {
  const re = /@import\s+(?:url\()?(['"])@hk\/weave-ui(\/[^'")\s]*)?\1\)?\s*;/g;
  return code.replace(re, (m, q, sub = "") => {
    return `@import ${q}@hk/weave-ui_${aliasModule}${sub}${q};`;
  });
}

/**
 * title: "something" → title: "vX.Y.Z/something"
 * - 이미 vX.Y.Z/ 로 시작하거나 head/ 로 시작하면 스킵
 * - 작은따옴표/큰따옴표/백틱 모두 처리
 */
function prefixStoryTitle(code, folderName) {
  const re = /(\btitle\s*:\s*)(["'`])([^"'`]+)\2/g;
  return code.replace(re, (full, pre, quote, inner) => {
    const t = inner.trim();
    if (t.startsWith(`${folderName}/`) || /^head\//i.test(t)) {
      return full; // 이미 접두가 있으면 그대로
    }
    return `${pre}${quote}${folderName}/${t}${quote}`;
  });
}

async function rewriteImportsRecursively(folder, aliasModule, folderName) {
  // ✅ CSS/SCSS까지 포함해서 처리
  const exts = /\.(mdx|[cm]?[jt]sx?|css|scss)$/i;
  const ents = await fsp.readdir(folder, { withFileTypes: true });
  for (const e of ents) {
    const p = path.join(folder, e.name);
    if (e.isDirectory()) {
      await rewriteImportsRecursively(p, aliasModule, folderName);
    } else if (e.isFile() && exts.test(e.name)) {
      const raw = await fsp.readFile(p, "utf8");
      let next = raw;

      if (/\.(css|scss)$/i.test(e.name)) {
        // CSS/SCSS: @import 치환만 수행
        next = replaceWeaveCssAtImport(next, aliasModule);
      } else {
        // JS/TS/MDX: import 치환 + title 보정
        next = replaceWeaveImports(next, aliasModule);
        next = prefixStoryTitle(next, folderName);
      }

      if (next !== raw) {
        await fsp.writeFile(p, next, "utf8");
        log(`rewrite: ${path.relative(repoRoot, p)}`);
      }
    }
  }
}

function run(cmd, args, opts = {}) {
  return new Promise((resolve, reject) => {
    log(`$ ${cmd} ${args.join(" ")}`);
    const cp = spawn(cmd, args, {
      stdio: "inherit",
      shell: process.platform === "win32",
      ...opts,
    });
    cp.on("exit", (code) => {
      if (code === 0) resolve();
      else reject(new Error(`${cmd} exited with code ${code}`));
    });
  });
}

async function main() {
  const pkg = await readJson(path.join(repoRoot, "package.json"));
  const version = pkg.version;
  if (!version) throw new Error("package.json version not found");

  const folderName = `v${version}`; // e.g. v0.2.0
  const aliasModule = toAliasName(version); // e.g. v0_2_0
  const aliasPkg = `@hk/weave-ui_${aliasModule}`; // e.g. @hk/weave-ui_v0_2_0

  const srcHead = path.join(storiesRoot, "head");
  const dstVer = path.join(storiesRoot, folderName);

  // 1) stories/head 복제 → stories/v{version}
  if (!fs.existsSync(srcHead)) {
    throw new Error(`Not found: ${path.relative(repoRoot, srcHead)}`);
  }
  await rimraf(dstVer);
  await copyDir(srcHead, dstVer);
  log(`copied: stories/head -> stories/${folderName}`);

  // 2) stories/v{version} 내부 import & title & CSS @import 치환
  await rewriteImportsRecursively(dstVer, aliasModule, folderName);

  // 3) npm 캐시 클리어 & alias 패키지 설치
  //    alias 문법: <alias>@npm:<real>@<version>
  const realPkg = "@hk/weave-ui";
  const aliasSpec = `${aliasPkg}@npm:${realPkg}@${version}`;

  await run("npm", ["cache", "clean", "--force"]);
  // devDependencies에 넣고 싶으면 --save-dev, prod로 넣고 싶으면 --save
  await run("npm", ["i", "--save-dev", aliasSpec]);

  log(`done: stories/${folderName}, installed ${aliasSpec}`);
}

