import {
  MutationFunction,
  UseInfiniteQueryOptions,
  UseMutationOptions,
  UseQueryOptions,
} from '@tanstack/react-query'

export const queryOption = <T extends unknown[], J>(
  key: string[],
  fn: (...payload: T) => Promise<J>
) => {
  return (...payload: T) =>
    ({
      queryKey: [...key, ...payload],
      queryFn: () => fn(...payload),
      staleTime: Infinity,
      refetchOnWindowFocus: false,
    }) satisfies UseQueryOptions<J>
}

export const mutationOption = <T, K>(key: string[], fn: MutationFunction<T, K>) => {
  return () =>
    ({
      mutationKey: key,
      mutationFn: fn,
      retry: 3,
    }) satisfies UseMutationOptions<T, unknown, K>
}

export const infiniteQueryOption = <TParam extends unknown[], TResult>(
  key: string[],
  fn: (...args: TParam) => Promise<TResult>
) => {
  return (...args: TParam) =>
    ({
      queryKey: [...key, ...args],
      queryFn: ({ pageParam }) => {
        if (!pageParam) return fn(...args)

        args.map((arg, index) => {
          if (typeof arg === 'object' && arg !== null) {
            args[index] = { ...arg, ...pageParam } as TParam[number]
          }
        })

        return fn(...args)
      },
      getNextPageParam: (lastPage) => lastPage,
      initialPageParam: undefined,
      staleTime: Infinity,
      refetchOnWindowFocus: false,
    }) satisfies UseInfiniteQueryOptions<TResult, unknown, TResult>
}

const fs = require('fs').promises
const path = require('path')
const { exec } = require('child_process')

const directoryPath = path.join(__dirname, '../libs')
const outputFilePath = path.join(__dirname, '../src/options')

async function processFolder(folder) {
  const domainFolder = path.join(directoryPath, folder)
  const isDirectoryDomainFolder = await fs.lstat(domainFolder).catch(() => false)
  if (!isDirectoryDomainFolder || !isDirectoryDomainFolder.isDirectory()) return

  const files = await fs.readdir(domainFolder).catch((err) => {
    console.error(`❌ ./libs에 특정 파일이 오류가 있는 것 같아요: ${err}`)
  })

  await Promise.all(
    files.map(async (file) => {
      if (file !== 'domain.ts' && file !== 'adaptor.ts' && path.extname(file) === '.ts') {
        const content = await fs.readFile(path.join(domainFolder, file), 'utf8')
        const fileName = file.replace('.ts', '')
        const functionNameMatches = content.match(
          /^(?<!\/\/\s*|\/\*\s*)export\s+const\s+(\w+)\s*=\s*(?:async\s*)?$begin:math:text$([^)]*)$end:math:text$/gm
        )

        const functionsNames = []
        let newContent = ''

        if (functionNameMatches) {
          functionNameMatches.forEach((match) => {
            const matchArr = match.split(' ')
            const functionName = matchArr[2]
            const folderName = path.basename(domainFolder)
            const key = `["${folderName}","${functionName}"]`

            newContent += `
export const ${functionName}Key = ${key};
export const ${functionName}QueryOption = option.queryOption(${functionName}Key, ${functionName});
export const ${functionName}MutationOption = option.mutationOption(${functionName}Key, ${functionName});
export const ${functionName}InfiniteQueryOption = option.infiniteQueryOption(${functionName}Key, ${functionName});
`
            functionsNames.push(functionName)
          })
        }
        if (functionsNames.length === 0) return
        newContent =
          `import { ${functionsNames.join(', ')} } from "#libs/${folder}/${fileName}";\nimport * as option from "#src/utils/query";\n` +
          newContent

        const outputFolder = path.join(outputFilePath, folder)
        if (!(await fs.stat(outputFolder).catch(() => false))) {
          await fs.mkdir(outputFolder, { recursive: true })
        }

        const outputFile = path.join(outputFolder, `${fileName}Options.ts`)
        await fs.writeFile(outputFile, newContent, 'utf8')

        exec(`npx prettier --write ${outputFile}`, (err) => {
          if (err) {
            console.error(`❌ prettier에서 오류가 났어요: ${err}`)
          }
        })
      }
    })
  )
}

