interface LazyPopupProps {
  open: boolean
  lazy?: boolean
  children: React.ReactNode
}

export const LazyPopup = ({ open, lazy = false, children }: LazyPopupProps) => {
  const [loaded, setLoaded] = useState(!lazy)

  const handleCapture = (e: React.SyntheticEvent) => {
    if (!lazy || loaded) return
    if ((e.target as HTMLElement).tagName === 'IMG') {
      setLoaded(true)
    }
  }

  const visible = open && (!lazy || loaded)

  return visible ? (
    <div className="popup" onLoadCapture={handleCapture}>
      {children}
    </div>
  ) : null
}

import { Children, PropsWithChildren } from 'react';
import { motion, AnimatePresence } from 'framer-motion';

type StepProps = PropsWithChildren<{
  release?: boolean;
  step: number;
}>;

/**
 * Step 컴포넌트
 * @param {ReactElement[]} [children] - 자식 컴포넌트
 * @param {boolean} [release] - 릴리즈 모드
 * @param {number} step - 현재 스텝 번호
 * @returns {JSX.Element} Step 컴포넌트
 */
export function Step({ children, release, step }: StepProps) {
  if (release) return children;

  const steps = Children.toArray(children);

  if (step >= steps.length) return null;

  return (
    <AnimatePresence mode="wait">
      <motion.div
        key={step}
        initial={step === 0 ? false : { opacity: 0, x: 20 }}
        animate={{ opacity: 1, x: 0 }}
        exit={{ opacity: 0, x: -20 }}
        transition={{ duration: 0.3 }}
      >
        {steps[step]}
      </motion.div>
    </AnimatePresence>
  );
}

