import { useEffect, useState } from 'react';
import { useDebounce, usePreservedCallback } from 'react-simplikit';

/**
 * 로컬 스토리지와 상태 값을 동기화하는 커스텀 훅입니다.
 */
export function useStorage<T>(key: string, initialValue?: T) {
  const [value, setValue] = useState<T>(() => {
    try {
      const storedValue = localStorage.getItem(key);
      if (storedValue !== null) return JSON.parse(storedValue);
      if (initialValue !== undefined) localStorage.setItem(key, JSON.stringify(initialValue));
      return initialValue;
    } catch (error) {
      console.error('Failed to parse stored value:', error);
      return initialValue;
    }
  });

  const debounceStorage = useDebounce((key: string, value?: string) => {
    if (value !== undefined) {
      localStorage.setItem(key, value);
    } else {
      localStorage.removeItem(key);
    }
  }, 300);

  const setStorageValue = usePreservedCallback((value?: T) => {
    const newValue = value === undefined ? undefined : JSON.stringify(value);

    const event = new StorageEvent('storage', {
      key,
      newValue: newValue ?? null,
      storageArea: localStorage,
      url: window.location.href,
    });
    window.dispatchEvent(event);
    debounceStorage(key, newValue);
  });

  useEffect(() => {
    const handleStorageChange = (event: StorageEvent) => {
      if (event.key !== key) return;
      if (event.storageArea !== localStorage) return;
      if (!document.hasFocus()) return;

      try {
        setValue(event.newValue ? JSON.parse(event.newValue) : undefined);
      } catch (error) {
        console.error('Invalid storage event data:', error);
      }
    };

    window.addEventListener('storage', handleStorageChange);
    return () => window.removeEventListener('storage', handleStorageChange);
  }, [key]);

  return [value, setStorageValue] as const;
}

