import { Dialog } from './Dialog';          // ✨ 자신이 쓰는 Dialog 컴포넌트로 변경
import {
  ReactNode,
  useCallback,
  useMemo,
  useRef,
  useState,
} from 'react';

interface ConfirmProviderProps {
  children: ReactNode;
  defaultSlot?: ReactNode;
  confirmText?: string;
  cancelText?: string;
}

export function ConfirmProvider({
  children,
  defaultSlot,
  confirmText = '확인',
  cancelText = '취소',
}: ConfirmProviderProps) {
  /** 모달 노출 여부 */
  const [open, setOpen] = useState(false);

  /** 모달 본문(슬롯) */
  const [slot, setSlot] = useState<ReactNode>(defaultSlot);

  /** “나중에 실행할” 콜백 & 인자 저장소 */
  const storedCallback = useRef<((...args: unknown[]) => unknown) | null>(null);
  const storedArgs = useRef<unknown[]>([]);

  /* ---------- 핸들러 ---------- */
  const close = useCallback(() => setOpen(false), []);

  const apply = useCallback(() => {
    storedCallback.current?.(...storedArgs.current);
    close();
  }, [close]);

  /** openConfirm: 콜백 + 슬롯 → 래핑된 함수 반환 */
  const openConfirm = useCallback(
    <T extends unknown[]>(
      fn: (...args: T) => unknown,
      customSlot?: ReactNode,
    ) => {
      return (...args: T) => {
        if (customSlot !== undefined) setSlot(customSlot);
        storedCallback.current = (...inner) => fn(...(inner as T));
        storedArgs.current = args;
        setOpen(true);
      };
    },
    [],
  );

  /** Context 값은 메모이제이션으로 안정화 */
  const contextValue = useMemo(() => ({ openConfirm }), [openConfirm]);

  return (
    <ConfirmContext.Provider value={contextValue}>
      {children}

      {/* 실제 다이얼로그 */}
      <Dialog open={open} onClose={close}>
        <Dialog.Content>{slot}</Dialog.Content>
        <Dialog.Footer
          handleApply={apply}
          handleClose={close}
          confirmText={confirmText}
          cancelText={cancelText}
        />
      </Dialog>
    </ConfirmContext.Provider>
  );
}

