import { Dialog, Slot } from '#lib/main';
import {
  cloneElement,
  isValidElement,
  MouseEvent,
  PropsWithChildren,
  ReactElement,
  ReactNode,
  RefObject,
  useRef,
  useState,
} from 'react';

type CustomChildren<T extends HTMLElement> = (open: boolean, ref?: RefObject<T | null>) => ReactNode;

export function Magnifying<T extends HTMLElement>({
  children,
  asChild,
  modal = <Dialog.Content />,
}: {
  asChild?: boolean;
  children?: CustomChildren<T>;
  modal?: ReactElement;
}) {
  const ref = useRef<T>(null);
  const Comp = asChild ? Slot : 'div';
  const [open, setOpen] = useState(false);

  const handleClose = () => setOpen(false);

  const handleOpen = (e: MouseEvent) => {
    const { target } = e;
    if (ref.current && target === ref.current) {
      setOpen(true);
    }
  };

  const innerChildren = useRef(children?.(true));
  const normalChildren = useRef(children?.(false, ref));

  return (
    <Comp child={asChild ? normalChildren.current : null} onClickCapture={handleOpen}>
      {normalChildren.current}
      <Dialog open={open} onClose={handleClose}>
        {isValidElement<PropsWithChildren>(modal)
          ? cloneElement(modal, { children: innerChildren.current })
          : innerChildren.current}
        <Dialog.Footer confirmText="확인" handleApply={handleClose} />
      </Dialog>
    </Comp>
  );
}
